import{_ as n,o as s,c as a,f as o,a as e}from"./app-v4ODCOL5.js";const t={},c=e(`<h2 id="第-20-章-前端监控、异常捕获与线上问题排查" tabindex="-1"><a class="header-anchor" href="#第-20-章-前端监控、异常捕获与线上问题排查" aria-hidden="true">#</a> 第 20 章 前端监控、异常捕获与线上问题排查</h2><h3 id="q1-你们项目的监控体系是怎么搭的-都监控些什么" tabindex="-1"><a class="header-anchor" href="#q1-你们项目的监控体系是怎么搭的-都监控些什么" aria-hidden="true">#</a> Q1 你们项目的监控体系是怎么搭的？都监控些什么？</h3><p><strong>考察点</strong>：能否把监控拆成清晰分类并说出每类的价值，而不是只答&quot;接了个 Sentry&quot;。答出三类 + 各自回答什么问题 + 怎么联动才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：前端监控分三块——错误监控回答&quot;哪里坏了&quot;、性能监控回答&quot;哪里慢了&quot;、行为埋点回答&quot;用户做了什么&quot;，三者靠同一个用户 ID 与时间轴串起来才能定位问题。</p></blockquote><ol><li>错误监控（Error Monitoring）：采集 JS 运行时错误、未捕获 Promise、资源加载失败、接口异常、框架层错误，价值是主动发现&quot;线上坏了&quot;，而不是等用户投诉。</li><li>性能监控（Performance Monitoring）：采集 LCP/INP/CLS 等核心指标、白屏时间、接口耗时、长任务，价值是把&quot;体验变差&quot;量化，并且必须看 P75/P95 分位而不是平均值。</li><li>行为埋点（Tracking）：PV/UV、点击、曝光、表单转化、路由跳转，价值是回答&quot;用户在哪一步流失&quot;，也是排障时的操作路径证据。</li><li>三块共享同一套标识：userId/deviceId、sessionId、release 版本、页面路径、时间戳；缺了这些就无法把&quot;错误 + 卡顿 + 用户操作&quot;拼成一条时间线。</li><li>再叠一层告警与看板：错误率、接口失败率、白屏数、P95 耗时按版本/页面/机型聚合，超阈值触发分级告警。</li><li>落地顺序：先错误监控（投入最小收益最快），再性能与埋点，最后做告警收敛与自动归因。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：只有错误监控够不够？答：不够。错误监控看不到&quot;没报错但很卡&quot;和&quot;用户压根没进来&quot;这两类问题，白屏有可能一条错误都不上报。</li><li>追问：为什么反复强调 release 版本？答：没有版本维度就无法把错误曲线对齐发布记录，也就无法在 1 分钟内判断&quot;是不是刚发的版本有问题&quot;。</li><li>陷阱：把监控等同于&quot;接了第三方 SDK&quot;，说不出自己项目采集了哪些字段、阈值怎么定，会显得没真正参与过。</li></ul><h3 id="q2-window-onerror-和-window-addeventlistener-error-有什么区别" tabindex="-1"><a class="header-anchor" href="#q2-window-onerror-和-window-addeventlistener-error-有什么区别" aria-hidden="true">#</a> Q2 <code>window.onerror</code> 和 <code>window.addEventListener(&#39;error&#39;)</code> 有什么区别？</h3><p><strong>考察点</strong>：考两套错误捕获入口的捕获范围差异，尤其是&quot;<code>onerror</code> 抓不到资源加载错误&quot;这一点。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>window.onerror</code> 只能抓 JS 运行时错误且只能挂一个；<code>addEventListener(&#39;error&#39;, fn, true)</code> 用捕获阶段能同时抓 JS 错误和资源加载失败，且可挂多个。</p></blockquote><ol><li>绑定方式：<code>onerror</code> 是属性，重复赋值会互相覆盖；<code>addEventListener</code> 可注册多个监听器，互不干扰。</li><li>捕获范围：<code>onerror</code> 只接收脚本运行时抛出的 <code>ErrorEvent</code>；资源加载失败触发的是普通 <code>Event</code>（<code>IMG</code>/<code>SCRIPT</code>/<code>LINK</code>/<code>VIDEO</code>），它发生在目标元素上、不冒泡，所以只有捕获阶段才能拦到。</li><li>参数差异：<code>onerror(message, source, lineno, colno, error)</code> 是五个参数；<code>addEventListener</code> 的回调用一个 <code>ErrorEvent</code> 对象，取 <code>event.message</code>、<code>event.error</code>、<code>event.filename</code>。</li><li>返回值语义：<code>onerror</code> 里 <code>return true</code> 会阻止浏览器默认的控制台输出；<code>addEventListener</code> 要用 <code>event.preventDefault()</code>。</li><li>都不能捕获的东西：未捕获的 Promise 拒绝（要单独监听 <code>unhandledrejection</code>）、框架内部吞掉的错误、跨域脚本的具体信息。</li><li>生产实践：两个都挂，<code>onerror</code> 作为兜底，<code>addEventListener(&#39;error&#39;, fn, true)</code> 处理资源失败，并用 <code>event instanceof ErrorEvent</code> 区分两类事件。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>window<span class="token punctuation">.</span><span class="token function-variable function">onerror</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">msg<span class="token punctuation">,</span> src<span class="token punctuation">,</span> line<span class="token punctuation">,</span> col<span class="token punctuation">,</span> err</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token function">report</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;js&#39;</span><span class="token punctuation">,</span> msg<span class="token punctuation">,</span> src<span class="token punctuation">,</span> line<span class="token punctuation">,</span> col<span class="token punctuation">,</span> <span class="token literal-property property">stack</span><span class="token operator">:</span> err <span class="token operator">&amp;&amp;</span> err<span class="token punctuation">.</span>stack <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token comment">// 不阻止默认输出，便于本地调试</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

window<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;error&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>e <span class="token keyword">instanceof</span> <span class="token class-name">ErrorEvent</span><span class="token punctuation">)</span> <span class="token keyword">return</span><span class="token punctuation">;</span> <span class="token comment">// JS 错误交给 onerror</span>
  <span class="token keyword">const</span> el <span class="token operator">=</span> e<span class="token punctuation">.</span>target<span class="token punctuation">;</span>
  <span class="token function">report</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;resource&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">tag</span><span class="token operator">:</span> el<span class="token punctuation">.</span>tagName<span class="token punctuation">,</span> <span class="token literal-property property">url</span><span class="token operator">:</span> el<span class="token punctuation">.</span>src <span class="token operator">||</span> el<span class="token punctuation">.</span>href <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 必须捕获阶段</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么资源错误一定要 <code>true</code>？答：资源错误事件不冒泡，只在捕获阶段经过 window，去掉 <code>true</code> 就永远收不到。</li><li>陷阱：说&quot;<code>onerror</code> 能捕获图片加载失败&quot;是错的，这是最常见的当场被问穿的点。</li><li>陷阱：<code>onerror</code> 里 <code>return true</code> 会吞掉控制台报错，开发阶段别乱用。</li></ul><h3 id="q3-怎么监控图片、脚本、样式这些资源加载失败" tabindex="-1"><a class="header-anchor" href="#q3-怎么监控图片、脚本、样式这些资源加载失败" aria-hidden="true">#</a> Q3 怎么监控图片、脚本、样式这些资源加载失败？</h3><p><strong>考察点</strong>：考资源错误监控的具体实现与坑：捕获阶段、<code>e.target</code> 判断、与 JS 错误区分、上报去重。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：在 <code>window</code> 上用捕获阶段监听 <code>error</code>，通过 <code>event.target</code> 拿到失败的元素，再用 <code>instanceof ErrorEvent</code> 把资源失败和 JS 错误分开上报。</p></blockquote><ol><li>监听方式：<code>window.addEventListener(&#39;error&#39;, handler, true)</code>，资源加载失败不会冒泡，必须捕获阶段。</li><li>取信息：<code>e.target.tagName</code> 区分 IMG/SCRIPT/LINK/VIDEO/AUDIO，<code>e.target.src || e.target.href</code> 取失败 URL，<code>e.target.currentSrc</code> 处理 <code>srcset</code>。</li><li>区分类型：<code>e instanceof ErrorEvent</code> 为真说明是 JS 错误，直接 return；否则按资源失败处理。</li><li>过滤噪声：上报前过滤埋点 GIF、<code>data:</code> 与 <code>blob:</code> URL、广告与第三方域名，否则日志会被噪声淹没。</li><li>上报字段：资源 URL、类型、页面路径、页面版本、资源版本、是否重试、<code>navigator.connection.effectiveType</code>（判断是否弱网）。</li><li>兜底价值：资源 404/超时往往是白屏与样式错乱的第一现场，比 JS 错误更早暴露，比如新版本 JS chunk 404。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：图片懒加载失败（还在 <code>data-src</code>）算不算资源错误？答：不算，此时还没真正发起请求；懒加载自身失败要用 <code>img.onerror</code> 单独兜底。</li><li>追问：怎么判断是弱网还是资源真挂了？答：结合 <code>effectiveType</code>、同批次失败率、CDN 回源日志看，失败集中在单个版本/单个文件通常是发布问题。</li><li>陷阱：把 <code>error</code> 监听写在 <code>document</code> 上也能收到大部分资源错误，但脚本错误事件目标是 window，写 <code>window</code> 更统一。</li></ul><h3 id="q4-未捕获的-promise-失败怎么监控-unhandledrejection-有什么坑" tabindex="-1"><a class="header-anchor" href="#q4-未捕获的-promise-失败怎么监控-unhandledrejection-有什么坑" aria-hidden="true">#</a> Q4 未捕获的 Promise 失败怎么监控？<code>unhandledrejection</code> 有什么坑？</h3><p><strong>考察点</strong>：考 Promise 拒绝不在 try/catch 与 <code>onerror</code> 覆盖范围内这个事实，以及 <code>reason</code> 可能不是 Error 的坑。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>Promise</code> 的拒绝不会触发 <code>error</code> 事件，必须监听 <code>window.addEventListener(&#39;unhandledrejection&#39;)</code>，而且它的 <code>reason</code> 可能只是字符串甚至 undefined，不能直接当 Error 用。</p></blockquote><ol><li>注册方式：<code>window.addEventListener(&#39;unhandledrejection&#39;, (e) =&gt; report(normalize(e.reason)))</code>，<code>e.promise</code> 能拿到那个 Promise，<code>e.reason</code> 是拒绝原因。</li><li>序列化坑：<code>reason</code> 可能是字符串、对象、<code>undefined</code>、带循环引用的对象；要写 <code>normalize()</code> 做安全转换，循环引用用 <code>JSON.stringify</code> 的 replacer 或 <code>WeakSet</code> 处理。</li><li>阻止默认输出：<code>e.preventDefault()</code> 可以阻止浏览器控制台打印，但排障阶段建议保留。</li><li>补偿事件：<code>rejectionhandled</code> 表示&quot;后来才被 catch&quot;，可用于给之前的上报打标记，减少误报率。</li><li>兼容兜底：部分老版本 Safari 不支持 <code>unhandledrejection</code>，兜底是统一约定业务层 <code>catch</code> 后手动上报，或用 <code>window.onerror</code> 兜住能冒泡的部分。</li><li>环境区分：Node 端是进程级 <code>unhandledRejection</code>，跟浏览器事件不是一回事，别答混。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么加了 <code>unhandledrejection</code> 还是漏报？答：常见的漏点是 <code>then</code> 链中间被吞、<code>async</code> 函数里忘了 <code>await</code>、以及第三方库自己 catch 后只 <code>console.log</code>。</li><li>陷阱：把 <code>e.reason.stack</code> 直接上报，<code>reason</code> 不是 Error 时得到 undefined，堆栈丢了反而更难定位。</li><li>陷阱：区分 <code>unhandledrejection</code>（未处理）与 <code>rejectionhandled</code>（事后处理），别答成一个。</li></ul><h3 id="q5-console-error-劫持有什么用-vue-和-react-的错误怎么统一收口" tabindex="-1"><a class="header-anchor" href="#q5-console-error-劫持有什么用-vue-和-react-的错误怎么统一收口" aria-hidden="true">#</a> Q5 <code>console.error</code> 劫持有什么用？Vue 和 React 的错误怎么统一收口？</h3><p><strong>考察点</strong>：考&quot;框架层错误捕获&quot;的两套机制，以及为什么必须同时做全局兜底。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>console.error</code> 劫持只是采集补充（框架捕获后打印的错误能被它捡到），真正的收口靠 Vue 的 <code>app.config.errorHandler</code> 与 React 的错误边界（Error Boundary）。</p></blockquote><ol><li><code>console.error</code> 劫持：重写 <code>console.error</code>，把参数序列化后上报，再调用原始方法；能捡到第三方库&quot;只打印不抛出&quot;的错误，但抓不到没打印的异常，且注意防重复上报。</li><li>Vue3：<code>app.config.errorHandler = (err, instance, info) =&gt; {}</code>，能捕获组件渲染、生命周期钩子、事件回调、<code>watch</code> 里的错误；Vue2 对应 <code>Vue.config.errorHandler</code>，另有 <code>warnHandler</code> 处理警告。</li><li>React：错误边界需类组件实现 <code>static getDerivedStateFromError</code>（渲染降级 UI）加 <code>componentDidCatch</code>（上报），React 16 起支持；错误边界只能捕获其子树中渲染期与生命周期里的错误。</li><li>React 的能力边界：事件回调、<code>setTimeout</code>、<code>Promise</code>、服务端渲染、边界自身抛出的错误都抓不到；React 18 起未捕获错误会卸载整棵树，所以边界是防白屏的必需品。</li><li>统一收口：框架层 handler 上报业务上下文（组件名、<code>info</code>），全局 <code>onerror</code>/<code>unhandledrejection</code> 兜底，两者用同一个上报函数与指纹去重。</li><li>上报要带组件栈：<code>instance.$options.name</code> 或 React 组件栈，否则只有一行堆栈无法定位到业务模块。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// Vue3 全局收口</span>
app<span class="token punctuation">.</span>config<span class="token punctuation">.</span><span class="token function-variable function">errorHandler</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">err<span class="token punctuation">,</span> instance<span class="token punctuation">,</span> info</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token function">report</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;vue&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">msg</span><span class="token operator">:</span> err<span class="token punctuation">.</span>message<span class="token punctuation">,</span> <span class="token literal-property property">stack</span><span class="token operator">:</span> err<span class="token punctuation">.</span>stack<span class="token punctuation">,</span>
    <span class="token literal-property property">component</span><span class="token operator">:</span> instance <span class="token operator">&amp;&amp;</span> instance<span class="token punctuation">.</span>$options<span class="token punctuation">.</span>name<span class="token punctuation">,</span> info <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token comment">// React 错误边界（类组件）</span>
<span class="token keyword">class</span> <span class="token class-name">Boundary</span> <span class="token keyword">extends</span> <span class="token class-name">React<span class="token punctuation">.</span>Component</span> <span class="token punctuation">{</span>
  state <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">broken</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
  <span class="token keyword">static</span> <span class="token function">getDerivedStateFromError</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token punctuation">{</span> <span class="token literal-property property">broken</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
  <span class="token function">componentDidCatch</span><span class="token punctuation">(</span><span class="token parameter">err<span class="token punctuation">,</span> info</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token function">report</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;react&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">msg</span><span class="token operator">:</span> err<span class="token punctuation">.</span>message<span class="token punctuation">,</span> <span class="token literal-property property">stack</span><span class="token operator">:</span> err<span class="token punctuation">.</span>stack<span class="token punctuation">,</span> <span class="token literal-property property">info</span><span class="token operator">:</span> info<span class="token punctuation">.</span>componentStack <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>state<span class="token punctuation">.</span>broken <span class="token operator">?</span> <span class="token operator">&lt;</span>Fallback <span class="token operator">/</span><span class="token operator">&gt;</span> <span class="token operator">:</span> <span class="token keyword">this</span><span class="token punctuation">.</span>props<span class="token punctuation">.</span>children<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：有了错误边界就不会白屏了吗？答：不会。边界只覆盖子树渲染错误，接口挂了、静态资源 404、根组件之外抛错仍会白屏，还要配合白屏检测。</li><li>陷阱：<code>componentDidCatch</code> 和 <code>getDerivedStateFromError</code> 混着答——前者做事（上报/副作用），后者返回 state 做降级渲染。</li><li>陷阱：劫持 <code>console.error</code> 后忘了处理原始调用与重复上报，导致同一条错误报两遍。</li></ul><h3 id="q6-一条错误日志应该带哪些字段" tabindex="-1"><a class="header-anchor" href="#q6-一条错误日志应该带哪些字段" aria-hidden="true">#</a> Q6 一条错误日志应该带哪些字段？</h3><p><strong>考察点</strong>：考采集字段的完整性。字段不全，后面所有定位都会缺证据。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：一条能用的错误日志 = 错误本身 + 环境 + 用户 + 版本 + 现场，缺任何一类都会让定位从&quot;看日志&quot;退化成&quot;猜&quot;。</p></blockquote><ol><li>错误本身：<code>message</code>、<code>stack</code>、错误类型（JS/资源/Promise/接口/框架）、文件名与行列号、错误指纹（用于聚合）。</li><li>版本与环境：<code>release</code>（版本号或 commit sha）、<code>environment</code>（prod/pre/staging）、构建时间、<code>dist</code>（灰度分支标识）。</li><li>用户与设备：<code>userId</code>、匿名 <code>deviceId</code>、<code>sessionId</code>；UA、浏览器与版本、操作系统、屏幕尺寸与 DPR、网络类型；注意做脱敏。</li><li>页面现场：当前 URL 与路由参数、referrer、是否首屏、页面停留时长、上一页来源。</li><li>上下文链路：<code>traceId</code>/<code>requestId</code> 用于和后端日志对齐，最近 N 条用户操作（breadcrumbs），最近的接口调用与耗时。</li><li>时间与计数：客户端时间戳 + 服务端接收时间（客户端时间不可信），同一指纹的累计次数与首次/末次发生时间。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么客户端时间不可信？答：用户可能改系统时间或时区错乱，做趋势分析必须以服务端接收时间为准。</li><li>陷阱：上报原始 URL 时带上 token、手机号等敏感参数，是合规事故，必须统一在 SDK 里做参数脱敏。</li><li>陷阱：堆栈被压在一行（未还原 source map）就丢失了文件与行列信息，光有 message 基本无法定位。</li></ul><h3 id="q7-埋点里的-pv、uv-到底怎么算-点击埋点怎么做" tabindex="-1"><a class="header-anchor" href="#q7-埋点里的-pv、uv-到底怎么算-点击埋点怎么做" aria-hidden="true">#</a> Q7 埋点里的 PV、UV 到底怎么算？点击埋点怎么做？</h3><p><strong>考察点</strong>：考埋点最基础的口径问题，以及 SPA 场景下路由监听与事件委托的实现。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：PV 是页面被打开/被路由切到的次数，每切一次加一；UV 是按人（userId 优先，其次匿名 ID）去重后的独立访客数，通常按天去重。</p></blockquote><ol><li>PV 口径：传统多页应用每次请求算一次；SPA 要在路由切换时手动上报，并且要明确&quot;同一页面 5 秒内来回切算几次&quot;这类规则，口径不定就会前后数据打架。</li><li>UV 口径：登录用户用 <code>userId</code>，未登录用 <code>deviceId</code>/cookie 匿名 ID，都没有才退化到 IP+UA（很不准）；登录后要做一次 ID 关联（identify），把匿名行为归到用户身上。</li><li>滑动去重：UV 依赖稳定的设备标识，cookie 被清、无痕模式、跨端同一用户都会导致重复计数，要写明口径而不是宣称&quot;精确&quot;。</li><li>点击埋点三种做法：手动调用 <code>track()</code>；全局事件委托按 <code>data-track</code> 属性匹配；封装指令/组件声明式埋点（如 <code>v-track</code>）。</li><li>事件委托的实现要点：SPA 要额外监听 <code>popstate</code> 与 monkey patch <code>history.pushState/replaceState</code> 才能抓到路由变化。</li><li>数据质量要点：埋点 ID 用常量枚举避免手写字符串；输入框内容一律不采集；埋点要跟业务需求一起评审，补埋点比改代码更容易漏。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// SPA 路由变化上报 PV（监听 history 前后都覆盖）</span>
<span class="token keyword">const</span> <span class="token function-variable function">trackPV</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">track</span><span class="token punctuation">(</span><span class="token string">&#39;pv&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">path</span><span class="token operator">:</span> location<span class="token punctuation">.</span>pathname<span class="token punctuation">,</span> <span class="token literal-property property">title</span><span class="token operator">:</span> document<span class="token punctuation">.</span>title <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">[</span><span class="token string">&#39;pushState&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;replaceState&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">k</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> raw <span class="token operator">=</span> history<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">;</span>
  history<span class="token punctuation">[</span>k<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter"><span class="token operator">...</span>args</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token function">raw</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> args<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token function">trackPV</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
window<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;popstate&#39;</span><span class="token punctuation">,</span> trackPV<span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 声明式点击埋点：事件委托</span>
document<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;click&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> el <span class="token operator">=</span> e<span class="token punctuation">.</span>target<span class="token punctuation">.</span><span class="token function">closest</span><span class="token punctuation">(</span><span class="token string">&#39;[data-track]&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>el<span class="token punctuation">)</span> <span class="token function">track</span><span class="token punctuation">(</span><span class="token string">&#39;click&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">id</span><span class="token operator">:</span> el<span class="token punctuation">.</span>dataset<span class="token punctuation">.</span>track <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：PV 和 UV 谁大？答：大多数场景 PV ≥ UV，但不做去重或口径混乱时会出现 UV 虚高，面试里要主动说明去重依据。</li><li>陷阱：只答&quot;PV 是访问量、UV 是访客数&quot;太浅，必须带出&quot;SPA 怎么切、UV 靠什么去重&quot;两个抓手。</li><li>陷阱：全局监听点击时忘了用 <code>closest</code> 处理事件代理链，导致子元素点击采集不到埋点 ID。</li></ul><h3 id="q8-线上出问题-你的排查思路是什么" tabindex="-1"><a class="header-anchor" href="#q8-线上出问题-你的排查思路是什么" aria-hidden="true">#</a> Q8 线上出问题，你的排查思路是什么？</h3><p><strong>考察点</strong>：考是否具备&quot;止血优先&quot;的工程意识。只讲怎么找根因、不讲先恢复服务，是典型的不合格回答。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：标准顺序是&quot;先止血、再定位、再修复、最后复盘&quot;——恢复服务永远优先于查清根因，因为用户损失是按分钟算的。</p></blockquote><ol><li>第一步止血：按影响面选最小代价手段——回滚版本、关闭灰度、切 Feature Flag 开关、降级非核心功能、限流或下线入口，目标是 5-10 分钟内让用户可用。</li><li>第二步定位：先确认影响面（全量还是部分版本/机型/地域/运营商），再把错误曲线、接口成功率、性能指标的时间点对齐发布记录与配置变更记录。</li><li>第三步定根因：从监控拿到指纹和堆栈，用 source map 还原到源码，结合操作路径与 <code>traceId</code> 查后端链路，能复现就本地复现。</li><li>第四步修复：小改动走热修 + 灰度验证，大改动走正常发布；修复后必须验证监控曲线回落，而不是只看自己电脑好了。</li><li>保留现场：排查期间先截图、导出错误列表与用户 ID 样本，别急着清缓存、重发版本，证据被覆盖会让复盘变成猜谜。</li><li>复盘：写清楚时间线、影响面、根因、止血动作、改进项（含责任人与截止时间），并把&quot;这次为什么没被监控提前发现&quot;作为必答项。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：还没定位就能回滚吗？答：能，而且应该。回滚是可逆动作，先恢复再在预发环境复现定位，这是标准做法。</li><li>追问：如果回滚也来不及（比如问题在服务端）？答：用 Feature Flag 或网关开关关闭故障功能，前端做降级兜底页，同时推动后端止血。</li><li>陷阱：一上手就去翻源码、加断点，把止血拖到半小时以后，面试官基本会直接判定不合格。</li></ul><h3 id="q9-时区与时间问题在前端有哪些坑" tabindex="-1"><a class="header-anchor" href="#q9-时区与时间问题在前端有哪些坑" aria-hidden="true">#</a> Q9 时区与时间问题在前端有哪些坑？</h3><p><strong>考察点</strong>：考 <code>Date</code> 的解析规则、时区处理原则，以及跨时区业务的时间口径约定。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：前端时间问题的根源是&quot;不带时区的时间字符串&quot;和 <code>Date</code> 的解析规则不一致，正确做法是服务端统一传时间戳或带时区的 ISO 字符串，前端只负责按需格式化。</p></blockquote><ol><li>解析规则差异：<code>new Date(&#39;2024-01-01&#39;)</code> 按 UTC 解析（东八区会显示为 1 月 1 日 08:00），而 <code>new Date(&#39;2024-01-01 10:00&#39;)</code> 按浏览器本地时区解析，两者混用必然出错。</li><li>兼容性坑：<code>new Date(&#39;2024-01-01 10:00&#39;)</code> 这种带空格的形式在部分 Safari 上返回 <code>Invalid Date</code>，要换成 <code>2024/01/01 10:00</code> 或直接传时间戳。</li><li>序列化坑：<code>toISOString()</code> 永远输出 UTC（带 <code>Z</code>），<code>toString()</code> 输出本地时区带偏移量的字符串，日志里混用会让时间线错乱。</li><li>服务端约定：接口统一传 10 位/13 位时间戳；必须传字符串时用带时区的 ISO 8601，禁止传&quot;2024-01-01 10:00:00&quot;这种无时区裸串。</li><li>业务判断：倒计时、活动开始/结束这类判断要用服务端下发的剩余时间或绝对的 UTC 时间戳，不要用本地 <code>Date.now()</code> 和本地格式化结果做比较。</li><li>展示与工具：展示层用 <code>Intl.DateTimeFormat</code> 或 dayjs/date-fns 指定 <code>timeZone</code> 转换；跨时区用户的时间展示要明确是&quot;用户本地时间&quot;还是&quot;业务统一时间&quot;，这属于产品口径，必须写进文档。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么线上会出现&quot;时间差 8 小时&quot;？答：服务端返回 ISO 字符串被当成本地时间解析，或前端用 <code>toISOString()</code> 直接展示 UTC，两者都会整体偏移一个时区。</li><li>陷阱：用 <code>new Date().getTimezoneOffset()</code> 手算偏移量做转换，遇到夏令时（DST）地区会算错，应该用 <code>Intl</code> 或成熟库。</li><li>陷阱：把&quot;时间差不等于时区问题&quot;搞混，先确认是偏移固定 8 小时（时区）还是随机偏差（客户端时间不准）。</li></ul><h3 id="q10-跨域脚本报错为什么变成-script-error-怎么解决" tabindex="-1"><a class="header-anchor" href="#q10-跨域脚本报错为什么变成-script-error-怎么解决" aria-hidden="true">#</a> Q10 跨域脚本报错为什么变成 <code>Script error.</code>？怎么解决？</h3><p><strong>考察点</strong>：考同源策略对错误信息的抹除机制，以及 <code>crossorigin</code> 属性与 CORS 响应头的配套要求。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：浏览器对跨域脚本抛出的错误只保留&quot;发生了错误&quot;这一事实，把消息和堆栈抹成 <code>Script error.</code>、行列号归零；解决办法是 <code>&lt;script crossorigin=&quot;anonymous&quot;&gt;</code> 加上 CDN 返回 <code>Access-Control-Allow-Origin</code>。</p></blockquote><ol><li>触发条件：脚本文件与页面不同源（含 CDN、子域名），且标签上没有 <code>crossorigin</code>，脚本内部抛错就会被抹除信息。</li><li>抹除内容：<code>message</code> 变成 <code>Script error.</code>，<code>filename</code>/<code>lineno</code>/<code>colno</code> 为空或 0，<code>error.stack</code> 拿不到。</li><li>解决方案：给 <code>&lt;script&gt;</code> 加 <code>crossorigin=&quot;anonymous&quot;</code>，同时 CDN 必须返回 <code>Access-Control-Allow-Origin</code>（通常为 <code>*</code> 或页面域名）；两个条件缺一不可。</li><li>构建工具配置：webpack 的 <code>output.crossOriginLoading: &#39;anonymous&#39;</code>，Vite 的 <code>build.rollupOptions.output.crossOriginLoading</code>，这样动态加载的 chunk 也带 crossorigin。</li><li>不受影响的情况：同源脚本、内联脚本、<code>&lt;script&gt;</code> 里的内联代码报错都能拿到完整信息；这说明&quot;只有静态资源上 CDN 才会被抹&quot;。</li><li>排查意义：线上错误里 <code>Script error.</code> 占比很高时，第一反应就是查 CDN 的 CORS 头是否配置或是否被网关改写，而不是去猜业务代码。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：只加 <code>crossorigin</code> 不加 CORS 头会怎样？答：脚本直接加载失败（被 CORS 拦截），比报错信息被抹更严重，所以头必须一起配。</li><li>追问：<code>crossorigin=&quot;use-credentials&quot;</code> 和 <code>anonymous</code> 区别？答：前者会带 cookie，此时响应头不能用 <code>*</code>，必须回具体域名；监控场景一般用 <code>anonymous</code>。</li><li>陷阱：以为&quot;改成同源部署&quot;就没事了，实际上静态资源走 CDN + 独立域名是常态，必须从 CORS 上解决。</li></ul><h3 id="q11-错误上报怎么设计-采样、去重、限流、批量分别怎么做" tabindex="-1"><a class="header-anchor" href="#q11-错误上报怎么设计-采样、去重、限流、批量分别怎么做" aria-hidden="true">#</a> Q11 错误上报怎么设计？采样、去重、限流、批量分别怎么做？</h3><p><strong>考察点</strong>：考上报通道的工程化设计。能说出&quot;防止上报把自己打挂&quot;的思考才算合格。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：上报设计的目标是&quot;关键错误不丢、重复错误不爆、上报本身不拖慢页面&quot;，手段是分级采样、指纹去重聚合、队列限流、批量发送。</p></blockquote><ol><li>采样：错误默认全量（量可控且每条都重要），性能与埋点按比例采样（如 10%-30%）；采样用 <code>userId</code> 哈希而非纯随机，保证同一用户行为可完整还原。</li><li>去重聚合：用&quot;错误消息 + 文件 + 行列 + 浏览器 + release&quot;生成指纹，相同指纹在时间窗内只上报一次并累加计数，把 N 条日志压成 1 条。</li><li>限流队列：内存里放定长队列（如 30 条），超出丢弃并打标记 <code>dropped: n</code>；同时限制单位时间上报请求数，防止错误风暴把上报接口也打挂。</li><li>批量上报：事件先进队列，定时（如 3-5 秒）或达到条数阈值时合并成一个请求发送，减少请求数；单条也要能立即发（严重错误优先）。</li><li>失败重试：上报失败先存 <code>localStorage</code>（带过期时间与容量上限），下次进入页面补发；注意补发要带原始时间戳，否则时间线错乱。</li><li>自我保护：上报逻辑全程 <code>try/catch</code>，SDK 自身报错绝不能影响业务；上报接口用独立域名或独立路径，避免与业务接口共享受限的并发连接。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么错误不采样？答：错误量级远小于埋点，且每条错误可能代表一个未覆盖的场景，采样会漏掉低频但致命的错误；量大的项目可对&quot;已知噪声&quot;单独降采样。</li><li>陷阱：只答&quot;攒一批一起发&quot;，说不出指纹去重与队列上限，会在追问&quot;错误风暴时怎么办&quot;时卡住。</li><li>陷阱：把埋点和错误的采样率设成同一个，导致低频错误全被采掉。</li></ul><h3 id="q12-页面卸载时的埋点怎么保证发出去-sendbeacon-有什么限制" tabindex="-1"><a class="header-anchor" href="#q12-页面卸载时的埋点怎么保证发出去-sendbeacon-有什么限制" aria-hidden="true">#</a> Q12 页面卸载时的埋点怎么保证发出去？<code>sendBeacon</code> 有什么限制？</h3><p><strong>考察点</strong>：考 <code>sendBeacon</code> 的适用场景与限制，以及&quot;用 <code>visibilitychange</code> 而不是 <code>unload</code>&quot;这个现代实践。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：结算类数据（停留时长、最终 CLS、离开前的错误）用 <code>navigator.sendBeacon</code> 在 <code>visibilitychange</code> 进入 hidden 时发送，它由浏览器在页面销毁后继续投递，比在 <code>unload</code> 里发 <code>fetch</code> 可靠。</p></blockquote><ol><li>为什么 <code>unload</code>/<code>beforeunload</code> 不可靠：移动端浏览器经常不触发这两个事件（切后台直接被回收），而且 <code>unload</code> 里的同步 XHR 已被规范废弃。</li><li>推荐时机：监听 <code>document.addEventListener(&#39;visibilitychange&#39;)</code>，当 <code>document.visibilityState === &#39;hidden&#39;</code> 时上报；这个时机的数据损失远小于 <code>unload</code>。</li><li><code>sendBeacon</code> 特性：以 POST 异步发送，不阻塞卸载，返回布尔值表示是否成功入队；浏览器保证尽力投递，页面关闭后仍然发送。</li><li>主要限制：不能自定义请求头，只能发 <code>text/plain</code>、<code>application/x-www-form-urlencoded</code>、<code>multipart/form-data</code> 三类；用 <code>Blob</code> 指定 <code>application/json</code> 会触发 CORS 预检，实践中多数团队直接发 <code>text/plain</code> 再让后端按 JSON 解析。</li><li>容量限制：单次载荷有大小上限（常见约 64KB），超限会抛异常，所以别把大段日志一把梭，要分批或截断。</li><li>兜底策略：<code>sendBeacon</code> 返回 false 或浏览器不支持时，退化用 <code>fetch(url, { method: &#39;POST&#39;, keepalive: true })</code>，再不行退化为 <code>img</code> GET 打点。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">flush</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>queue<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token keyword">return</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> payload <span class="token operator">=</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span>queue<span class="token punctuation">.</span><span class="token function">splice</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> ok <span class="token operator">=</span> navigator<span class="token punctuation">.</span>sendBeacon
    <span class="token operator">&amp;&amp;</span> navigator<span class="token punctuation">.</span><span class="token function">sendBeacon</span><span class="token punctuation">(</span><span class="token string">&#39;/log/report&#39;</span><span class="token punctuation">,</span> <span class="token keyword">new</span> <span class="token class-name">Blob</span><span class="token punctuation">(</span><span class="token punctuation">[</span>payload<span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;text/plain&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>ok<span class="token punctuation">)</span> <span class="token function">fetch</span><span class="token punctuation">(</span><span class="token string">&#39;/log/report&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">method</span><span class="token operator">:</span> <span class="token string">&#39;POST&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">body</span><span class="token operator">:</span> payload<span class="token punctuation">,</span> <span class="token literal-property property">keepalive</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
document<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;visibilitychange&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>document<span class="token punctuation">.</span>visibilityState <span class="token operator">===</span> <span class="token string">&#39;hidden&#39;</span><span class="token punctuation">)</span> <span class="token function">flush</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么不用 <code>beforeunload</code>？答：它只在用户主动关闭/刷新时触发，且会干扰用户操作；移动端切后台后再也不回来的场景它完全覆盖不到。</li><li>陷阱：在 <code>sendBeacon</code> 里自定义 <code>Content-Type: application/json</code>，结果触发预检、预检失败导致数据全丢，这是高频踩坑。</li><li>陷阱：把 CLS 在 <code>load</code> 时就上报，此时页面还没隐藏，得到的是不完整的 CLS 值。</li></ul><h3 id="q13-source-map-怎么用来还原线上错误-生产环境要注意什么" tabindex="-1"><a class="header-anchor" href="#q13-source-map-怎么用来还原线上错误-生产环境要注意什么" aria-hidden="true">#</a> Q13 Source Map 怎么用来还原线上错误？生产环境要注意什么？</h3><p><strong>考察点</strong>：考&quot;线上堆栈为什么不能用&quot;以及 map 的私有化流程：不公开、按版本归档、按行列还原。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：生产不部署可见的 <code>.map</code>，而是用 <code>hidden-source-map</code> 生成后私有上传到监控平台，上报时带上 release 与文件路径，平台按行列号从归档的 map 还原出源码位置。</p></blockquote><ol><li>生产为什么不暴露 map：<code>.map</code> 里的 <code>sourcesContent</code> 会包含完整源码，公网可访问等于源码泄露；同时攻击者能据此分析逻辑。</li><li><code>hidden-source-map</code> 的作用：照常生成 <code>.map</code> 文件，但不在 bundle 末尾写 <code>sourceMappingURL</code> 注释，浏览器不会自动去取，只有持有 map 的平台能还原。</li><li>相关模式对照：<code>source-map</code> 公开可用（适合内网/预发）、<code>hidden-source-map</code> 生成但不引用、<code>nosources-source-map</code> 保留行列映射但去掉源码内容，是折中方案。</li></ol><table><thead><tr><th>devtool（webpack）</th><th>是否生成 map</th><th>是否自动引用</th><th>是否含源码内容</th></tr></thead><tbody><tr><td><code>source-map</code></td><td>是</td><td>是</td><td>是</td></tr><tr><td><code>hidden-source-map</code></td><td>是</td><td>否</td><td>是</td></tr><tr><td><code>nosources-source-map</code></td><td>是</td><td>否</td><td>否</td></tr></tbody></table><ol start="4"><li>上传与关联：用 Sentry 的构建插件或自研 CI 步骤，把 map 以 <code>release + 文件路径</code> 为键传到监控平台；Vite 对应 <code>build.sourcemap: &#39;hidden&#39;</code>，同样在上传插件里处理。</li><li>还原实现：服务端用 <code>source-map</code> 库的 <code>SourceMapConsumer.originalPositionFor({ line, column })</code>，把压缩后的行列映射回源文件、原始行号与函数名；注意浏览器上报的 <code>colno</code> 从 1 开始，还原时要对应处理，差一位常常就定位到错误的上一行。</li><li>最常见的失败原因：版本对不上（发布后 map 被覆盖或删除）。必须以 hash 目录或 release 维度长期归档，禁止&quot;发完就删&quot;，同时保证上报里的文件路径与上传键一致。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么线上堆栈经常只有一行？答：代码被压缩成一行，没有 map 就只能看到压缩后的列号，无法对应业务代码。</li><li>陷阱：以为把 <code>.map</code> 免费放 CDN 就&quot;解决&quot;了还原问题，这是把源码直接给了所有人。</li><li>陷阱：用 <code>SourceMapConsumer</code> 时传的行列来自压缩代码没错，但忘了减列号偏移，导致定位总是偏一列。</li></ul><h3 id="q14-sentry-这类平台的核心能力是什么-接入要注意什么" tabindex="-1"><a class="header-anchor" href="#q14-sentry-这类平台的核心能力是什么-接入要注意什么" aria-hidden="true">#</a> Q14 Sentry 这类平台的核心能力是什么？接入要注意什么？</h3><p><strong>考察点</strong>：考对成熟监控平台能力项的理解（不只是&quot;能看报错&quot;），以及 release、source map、采样这些接入必需配置。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：Sentry 的价值是&quot;错误自动分组 + 上下文时间线 + 版本关联 + 性能与回放&quot;，接入的关键是把 release、source map 上传、采样率和脱敏配好。</p></blockquote><ol><li>错误分组（Grouping）：按归一化后的堆栈与错误信息生成指纹，把同一 bug 的上万条日志聚成一个 issue，并对相似错误做合并；支持自定义 <code>fingerprint</code>。</li><li>Breadcrumbs（面包屑）：自动采集 <code>console</code>、DOM 交互、路由切换、<code>fetch</code>/<code>XHR</code> 请求等事件，形成错误发生前的操作时间线，是&quot;还原用户操作路径&quot;的现成能力。</li><li>Release 与版本关联：初始化时传 <code>release</code>（版本号或 commit sha）和 <code>environment</code>、<code>dist</code>，就能按版本看错误、区分回归与存量问题，并在 issue 里看到&quot;首次出现在哪个版本&quot;。</li><li>Source Map：通过构建插件上传 map，堆栈直接显示源码文件与行号，还支持显示错误代码上下文片段。</li><li>性能监控：<code>tracesSampleRate</code> 开启事务采样，看页面加载、接口与慢事务；<code>replayIntegration</code>（会话回放）可录制用户操作，配合 <code>maskAllInputs</code> 做隐私脱敏。</li><li>用户与反馈：<code>Sentry.setUser({ id })</code> 关联用户，<code>ignoreErrors</code>/<code>beforeSend</code> 过滤噪声与脱敏，<code>showReportDialog</code> 提供用户主动反馈入口。接入注意：上报域名要能连通（必要时自建或走反向代理），采样率与配额要算成本。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：错误分组分错了怎么办？答：先看是不是堆栈被压缩导致归一化失败（map 没传），再考虑给该错误设置自定义 <code>fingerprint</code>，或调整 <code>ignoreErrors</code>。</li><li>陷阱：不配 <code>release</code> 直接接入，事后无法判断&quot;这个错误是新版本引入的还是历史存量&quot;，等于丢掉了最关键的判断依据。</li><li>陷阱：把 <code>tracesSampleRate</code> 设成 1.0 上线，量大时配额瞬间打满，性能数据全被丢弃。</li></ul><h3 id="q15-接口异常怎么监控-502-和超时具体怎么处理" tabindex="-1"><a class="header-anchor" href="#q15-接口异常怎么监控-502-和超时具体怎么处理" aria-hidden="true">#</a> Q15 接口异常怎么监控？502 和超时具体怎么处理？</h3><p><strong>考察点</strong>：考请求层监控的落地点（拦截器、错误码分类、失败率），以及线上 502/超时的完整处理动作。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：接口监控统一收口在请求拦截器里，按&quot;网络层 / HTTP 状态码 / 业务码&quot;三类分级上报并统计失败率；遇到 502 和超时先判断影响面，再决定降级、重试还是止血回滚。</p></blockquote><ol><li>拦截器收口：封装 <code>axios</code> 拦截器或 <code>fetch</code> 包装，在响应与错误分支统一上报，字段含接口路径、方法、状态码、业务码、耗时、是否超时、<code>traceId</code>；请求参数要脱敏。</li><li>错误码分类：网络层错误（断网、DNS、CORS 拦截、超时）说明请求没到或没回；HTTP 4xx 多为参数/鉴权问题（401 要触发登出跳登录）；5xx 是服务端问题；业务码（<code>code !== 0</code>）属于业务规则失败，不应计为&quot;接口故障&quot;。</li><li>失败率与耗时：失败率 = 失败数 / 总数，按接口 + 版本 + 地域维度聚合；耗时看 P95/P99 而不是平均，并区分服务端耗时与网络耗时。</li><li>重试策略：只对幂等的 GET 或显式幂等接口重试，用指数退避 + 抖动，限制次数（1-2 次）；POST 提交类接口严禁自动重试，否则会产生重复下单。</li><li>处理 502 的动作序列：先看是不是全站所有接口都 502（网关层问题，立即联系运维/后端止血）还是单接口（后端实例挂了），同时前端切降级数据或关闭该模块，并给出可重试的友好提示，而不是白屏或无限 loading。</li><li>处理超时的动作序列：确认是全部接口变慢还是个别接口；先看服务端 P95 是否同步上涨（是则后端问题），只有网络层慢则查 CDN/DNS/运营商；前端提高超时阈值、给慢接口加骨架屏与取消逻辑，必要时限制并发。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：接口全挂但页面是白屏，算接口问题还是前端问题？答：算前端问题。接口失败必须被前端兜住并渲染兜底 UI，白屏说明缺少错误态设计。</li><li>陷阱：把所有 <code>code !== 0</code> 都上报为接口错误，导致失败率虚高、告警噪声大，业务码和故障必须分开统计。</li><li>陷阱：给所有请求无脑加重试，POST 重复提交的线上事故就是这么来的。</li></ul><h3 id="q16-性能指标怎么采集上报-为什么看-p95-不看平均值" tabindex="-1"><a class="header-anchor" href="#q16-性能指标怎么采集上报-为什么看-p95-不看平均值" aria-hidden="true">#</a> Q16 性能指标怎么采集上报？为什么看 P95 不看平均值？</h3><p><strong>考察点</strong>：考 Core Web Vitals 的采集方式、<code>PerformanceObserver</code> 的使用、长任务与采样分位这几个工程点。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：用 <code>web-vitals</code> 或 <code>PerformanceObserver</code> 采集 LCP/INP/CLS/TTFB 与长任务，页面进入 hidden 时上报最终值，服务端按天聚合并以 P75 作为核心指标口径、同时看 P95 尾部。</p></blockquote><ol><li>核心指标：LCP（最大内容绘制，加载性能）、INP（交互到下一次绘制，响应性）、CLS（累积布局偏移，视觉稳定性）是当前 Core Web Vitals；CLS 是全生命周期累积值、INP 会随后续交互不断刷新，两者都必须在页面隐藏时才上报最终结果。</li><li>INP 的版本注意：Chrome 从 2024 年 3 月起用 INP 取代 FID 作为响应性核心指标，<code>web-vitals</code> 库相应提供 <code>onINP</code>；答 FID 时要说明这是旧指标。</li><li>采集方式：优先用 <code>PerformanceObserver</code> 监听 <code>largest-contentful-paint</code>、<code>layout-shift</code>、<code>event</code>、<code>longtask</code>、<code>navigation</code>、<code>resource</code> 等 entryType；<code>web-vitals</code> 是对这些的封装，能自动处理部分兼容与计算细节，业务项目直接用它更省事。</li><li>长任务：<code>longtask</code> 条目指主线程被占用超过 50ms 的任务，是卡顿的直接证据；上报时要带 attribution（归属元素/脚本）才能定位到具体代码。</li><li>采样率：性能数据按 10%-30% 采样即可，错误数据全量；采样按 <code>userId</code> 哈希做，避免同一用户时采时不采导致行为链断裂。</li><li>为什么看 P95：平均值会被大量快页面拉平，掩盖慢用户的真实体验；P95/P99 才能反映&quot;最差的那批用户有多差&quot;；但对外达标口径仍以官方的 P75 为准。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">import</span> <span class="token punctuation">{</span> onLCP<span class="token punctuation">,</span> onINP<span class="token punctuation">,</span> onCLS<span class="token punctuation">,</span> onTTFB <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;web-vitals&#39;</span><span class="token punctuation">;</span>

<span class="token keyword">const</span> <span class="token function-variable function">send</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">m</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> queue<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">name</span><span class="token operator">:</span> m<span class="token punctuation">.</span>name<span class="token punctuation">,</span> <span class="token literal-property property">value</span><span class="token operator">:</span> m<span class="token punctuation">.</span>value<span class="token punctuation">,</span> <span class="token literal-property property">rating</span><span class="token operator">:</span> m<span class="token punctuation">.</span>rating <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">[</span>onLCP<span class="token punctuation">,</span> onINP<span class="token punctuation">,</span> onCLS<span class="token punctuation">,</span> onTTFB<span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">fn</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">fn</span><span class="token punctuation">(</span>send<span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">reportAllChanges</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">new</span> <span class="token class-name">PerformanceObserver</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">list</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  list<span class="token punctuation">.</span><span class="token function">getEntries</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>e<span class="token punctuation">.</span>duration <span class="token operator">&gt;</span> <span class="token number">100</span><span class="token punctuation">)</span> <span class="token function">report</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;longtask&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">duration</span><span class="token operator">:</span> e<span class="token punctuation">.</span>duration <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">observe</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;longtask&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">buffered</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：CLS 为什么不能一加载完就上报？答：用户可能继续滚动、图片继续加载导致新的布局偏移，只有页面隐藏时的值才是最终 CLS。</li><li>追问：FID 和 INP 区别？答：FID 只测首次交互的输入延迟，INP 覆盖整页所有交互并算到绘制完成，更贴近真实卡顿感受，所以取代了 FID。</li><li>陷阱：只采集不上报维度（页面、机型、版本），拿到一个 P95 数字也没法定位是哪一页慢。</li></ul><h3 id="q17-曝光埋点怎么做-为什么不能-可见就算曝光" tabindex="-1"><a class="header-anchor" href="#q17-曝光埋点怎么做-为什么不能-可见就算曝光" aria-hidden="true">#</a> Q17 曝光埋点怎么做？为什么不能&quot;可见就算曝光&quot;？</h3><p><strong>考察点</strong>：考 <code>IntersectionObserver</code> 的使用与曝光判定规则（可见比例 + 停留时长 + 去重）。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：曝光埋点用 <code>IntersectionObserver</code> 观察目标元素，只有&quot;可见面积达到阈值并持续足够时长&quot;才算一次有效曝光，且同一元素在同一会话内只上报一次。</p></blockquote><ol><li>判定规则：通常要求可见比例 ≥ 50%（<code>threshold</code>）且持续 ≥ 1 秒，避免快速滑过、闪现的元素被算成曝光，否则数据会虚高几倍。</li><li>基础实现：<code>new IntersectionObserver(cb, { threshold: [0.5], rootMargin: &#39;0px&#39; })</code>，在回调里用 <code>entry.intersectionRatio</code> 和 <code>isIntersecting</code> 判断。</li><li>停留时长：<code>isIntersecting</code> 为真时记开始时间，为假时结算时长；不足阈值的丢弃，跨过阈值的才上报。</li><li>去重：用一个集合或元素上的标记位记录已曝光的 ID，同一元素同一会话不再重复上报；列表复用（虚拟滚动）时要按数据 ID 而不是 DOM 节点去重。</li><li>生命周期：组件卸载时要 <code>observer.unobserve(el)</code> / <code>disconnect()</code>，否则会造成内存泄漏和&quot;幽灵曝光&quot;；动态插入的节点要补观察。</li><li>兼容与兜底：<code>IntersectionObserver</code> 兼容性已经很好，极老环境可退化用 <code>scroll</code> + <code>getBoundingClientRect</code> 并做节流，但成本高，优先要求降级不采集而不是硬实现。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> seen <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> io <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">IntersectionObserver</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">entries</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  entries<span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">entry</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> id <span class="token operator">=</span> entry<span class="token punctuation">.</span>target<span class="token punctuation">.</span>dataset<span class="token punctuation">.</span>exposeId<span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>entry<span class="token punctuation">.</span>isIntersecting<span class="token punctuation">)</span> <span class="token punctuation">{</span>
      entry<span class="token punctuation">.</span>target<span class="token punctuation">.</span>_t <span class="token operator">=</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>entry<span class="token punctuation">.</span>target<span class="token punctuation">.</span>_t <span class="token operator">&amp;&amp;</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> entry<span class="token punctuation">.</span>target<span class="token punctuation">.</span>_t <span class="token operator">&gt;=</span> <span class="token number">1000</span> <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span>seen<span class="token punctuation">.</span><span class="token function">has</span><span class="token punctuation">(</span>id<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
      seen<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span>
      <span class="token function">track</span><span class="token punctuation">(</span><span class="token string">&#39;expose&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> id<span class="token punctuation">,</span> <span class="token literal-property property">ratio</span><span class="token operator">:</span> entry<span class="token punctuation">.</span>intersectionRatio <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
      entry<span class="token punctuation">.</span>target<span class="token punctuation">.</span>_t <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">threshold</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token number">0.5</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么用 <code>IntersectionObserver</code> 而不是监听 <code>scroll</code>？答：<code>scroll</code> 回调在主线程高频触发、要手动算位置，容易引起卡顿；<code>IntersectionObserver</code> 由浏览器异步调度，性能与代码复杂度都更优。</li><li>陷阱：把 <code>threshold: 0</code> 当成默认合理值，只要露出 1 像素就上报，曝光量会严重虚高。</li><li>陷阱：用 DOM 节点做去重键，列表复用后节点被重新赋值，导致同一商品的曝光被重复计或漏计。</li></ul><h3 id="q18-无埋点-全埋点-的原理是什么-和手动埋点怎么选" tabindex="-1"><a class="header-anchor" href="#q18-无埋点-全埋点-的原理是什么-和手动埋点怎么选" aria-hidden="true">#</a> Q18 无埋点（全埋点）的原理是什么？和手动埋点怎么选？</h3><p><strong>考察点</strong>：考无埋点的实现原理与真实代价，能说出&quot;不是银弹&quot;才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：无埋点靠全局事件委托自动采集所有点击/浏览行为并记录元素路径，再由配置平台圈选定义有效事件；它降低开发成本，但数据量大、语义弱、路径不稳定。</p></blockquote><ol><li>采集原理：在 <code>document</code> 上代理 <code>click</code>、<code>change</code>、<code>input</code> 等事件，命中后采集元素路径（标签 + id + class + <code>nth-child</code>，或优先取 <code>data-track</code> 语义标记）、页面、用户、时间。</li><li>上报与圈选：SDK 先全量上报&quot;原始行为流&quot;，产品在可视化平台圈选某个按钮，平台生成配置下发，SDK 再按配置产出正式事件；也有 SDK 侧只上报被配置命中的行为以节省流量。</li><li>优点：新增功能自动有数据、可回溯历史行为（今天能圈选上周的按钮）、埋点需求不占用发版周期。</li><li>缺点一：数据量远大于手动埋点，成本与噪声都高；缺点二：路径表达式依赖 DOM 结构，改一次样式/换一次框架结构，历史配置就失效。</li><li>缺点二延伸：语义弱，<code>nth-child(3)</code> 说不出业务含义；动态列表、弹窗、Canvas、跨端组件里的行为难以准确归属。</li><li>实践取舍：核心业务指标（下单、支付、关键转化）用手动埋点保证准确与口径稳定，通用行为分析用无埋点补充；两者必须共用同一套用户标识与事件模型，否则数据无法对齐。合规上要默认不采集输入内容并支持一键关闭。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：无埋点能替代手动埋点吗？答：不能。核心口径要求稳定可审计，DOM 路径漂移会让历史数据断裂，关键指标必须手动埋。</li><li>陷阱：把无埋点说成&quot;零成本&quot;，实际是成本从开发期转移到了数据治理与平台建设期。</li><li>陷阱：忽略元素路径在 Vue/React 组件复用下的不稳定性，圈选配置在发版后集体失效。</li></ul><h3 id="q19-线上日志与用户反馈渠道怎么设计" tabindex="-1"><a class="header-anchor" href="#q19-线上日志与用户反馈渠道怎么设计" aria-hidden="true">#</a> Q19 线上日志与用户反馈渠道怎么设计？</h3><p><strong>考察点</strong>：考移动端调试与&quot;用户侧证据链&quot;的搭建，重点在 ID 关联和操作路径回放。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：线上日志渠道 = 可开关的调试面板 + 统一的用户标识 + 操作路径时间线 + 低门槛的反馈入口，核心目标是&quot;用户一句话，我们能还原他面前的屏幕和操作序列&quot;。</p></blockquote><ol><li>调试面板：移动端用 vConsole 或 eruda，但必须做开关——URL 带 <code>debug=1</code>、指定用户白名单或后端下发配置，禁止对全体用户默认开启（既影响性能也有信息暴露风险）。</li><li>用户 ID 关联：登录后调用 <code>setUser({ id })</code>，未登录用匿名 <code>deviceId</code>；从匿名变已登录时上报一次关联事件（identify/alias），否则同一用户的行为被拆成两段。</li><li>操作路径回放：靠 breadcrumbs 记录&quot;路由切换 + 点击 + 接口请求与响应码 + 错误&quot;的带时间戳序列；更完整的是 DOM 录制回放（如 rrweb 或 Sentry Replay），但必须做隐私脱敏，输入框内容一律 mask。</li><li>日志关联后端：所有请求带 <code>traceId</code>/<code>requestId</code>，前端错误日志里保存该 ID，排障时用它在服务端日志里拉出完整调用链。</li><li>用户反馈入口：在页面内提供低门槛反馈（一键反馈自动附带当前页面、版本、用户 ID、最近错误），Sentry 的 <code>showReportDialog</code> 可以让用户补充&quot;我做了什么&quot;；客服系统要与监控打通，避免反馈与日志两套孤立数据。</li><li>移动端与桌面端补充手段：iOS 用 Safari 开发菜单、Android 用 Chrome <code>chrome://inspect</code> 远程调试；不方便连线的场景用 vConsole + 上报截图/录屏，客服侧收集机型和系统版本作为兜底证据。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 vConsole 一定要开关？答：全量开启会拖慢首屏、暴露接口参数与存储内容，还可能被恶意用户当作调试入口利用。</li><li>陷阱：只做错误上报不做操作路径，拿到堆栈也只能知道&quot;哪个函数炸了&quot;，说不出&quot;用户在做什么操作时炸的&quot;。</li><li>陷阱：忽略匿名到登录的 ID 关联，导致同一个用户被算成两个 UV，转化漏斗也对不上。</li></ul><h3 id="q20-样式错乱、兼容性崩溃、localstorage-写满这几种事故怎么快速处理" tabindex="-1"><a class="header-anchor" href="#q20-样式错乱、兼容性崩溃、localstorage-写满这几种事故怎么快速处理" aria-hidden="true">#</a> Q20 样式错乱、兼容性崩溃、<code>localStorage</code> 写满这几种事故怎么快速处理？</h3><p><strong>考察点</strong>：考三类高频&quot;非崩溃型&quot;事故的判断顺序与止血动作，重点是有没有可执行动作。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：三类事故的共同处理逻辑是&quot;先判断是不是刚发的版本引起的，是就立即回滚或切开关，再在预发复现定位&quot;，而不是先改代码。</p></blockquote><ol><li>样式错乱的判断顺序：先看是不是 HTML 与 CSS 版本不匹配（HTML 已更新、CSS 还是 CDN 缓存的旧文件，或反之），再看是否灰度/AB 导致新旧样式共存，最后才怀疑选择器冲突与 CSS-in-JS 顺序。</li><li>样式错乱止血动作：回滚发布；无法回滚时临时在 CDN 刷新/加版本号参数强制更新；长期修法是 HTML 用 <code>no-cache</code>、静态资源用内容哈希长缓存、发布顺序先传资源后切 HTML，并让 CSS 优先级规则统一到构建层。</li><li>兼容性崩溃的典型形态：低版本浏览器不支持可选链、空值合并、<code>BigInt</code>、私有字段等新语法，解析阶段就抛 <code>SyntaxError</code>，整包不执行直接白屏。</li><li>兼容性处理动作：确认报错是 <code>SyntaxError</code> 且集中在特定浏览器版本后，立即回滚；根治靠构建 target 降级 + polyfill（<code>core-js</code>）+ 语法检查（在入口用一小段独立脚本探测能力，给出升级浏览器提示而不是白屏）。</li><li><code>localStorage</code> 写满：写入超限抛 <code>QuotaExceededError</code>（部分浏览器是 <code>NS_ERROR_DOM_QUOTA_REACHED</code>，老版 Safari 无痕模式下甚至直接抛异常），表现为功能静默失效、登录态写不进去。</li><li><code>localStorage</code> 处理动作：所有读写统一走封装并 <code>try/catch</code>；设容量与键数量上限，用类似 LRU 的策略清理过期键；大对象改用 IndexedDB；同时给写入失败一条降级路径（内存缓存），并上报&quot;存储写入失败&quot;这个事件本身，否则这类故障永远是静默的。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么样式错乱要优先怀疑缓存？答：代码本身没变、只是资源版本不一致时，回滚代码是无效动作；而缓存不一致恰恰是发布流程问题，能一次修好。</li><li>陷阱：把 <code>QuotaExceededError</code> 当成&quot;浏览器不支持 localStorage&quot;，不去做容量治理，问题会周期复现。</li><li>陷阱：兼容性崩溃不看浏览器版本分布就改代码，结果改了也用不上——用户根本升不了浏览器，正确做法是先提示升级再逐步降级支持。</li></ul><h3 id="q21-上线后-cdn-缓存不更新、旧版本资源-404-怎么解决" tabindex="-1"><a class="header-anchor" href="#q21-上线后-cdn-缓存不更新、旧版本资源-404-怎么解决" aria-hidden="true">#</a> Q21 上线后 CDN 缓存不更新、旧版本资源 404 怎么解决？</h3><p><strong>考察点</strong>：考缓存策略与发布顺序的配合，以及 &quot;Loading chunk failed&quot; 这类典型故障的前端兜底。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：入口 HTML 必须不缓存、带内容哈希的静态资源才长缓存，发布时先传资源再切 HTML；旧版本 chunk 404 要保留多版本资源并在前端做加载失败自动重试或提示刷新。</p></blockquote><ol><li>缓存策略分工：<code>index.html</code> 用 <code>Cache-Control: no-cache</code>（或不缓存）保证入口永远最新；JS/CSS/图片用文件名内容哈希 + 一年长缓存，靠换名实现&quot;更新&quot;。</li><li>发布顺序：先把新版本静态资源全量上传到 CDN，确认可访问，再更新 HTML 入口；顺序反了就会出现&quot;新 HTML 引用不存在的资源&quot;，也就是白屏。</li><li>旧版本资源 404 的成因：用户停留在旧页面，此时发新版把旧 chunk 删了，用户点击跳转再懒加载旧 chunk 就 404，报 <code>Loading chunk N failed</code> 或 <code>Failed to fetch dynamically imported module</code>。</li><li>止血动作：立即恢复被删的旧版本资源目录（保留 N 个版本或 N 天），这是最快的恢复手段；无法恢复时让用户刷新页面拿到新版本。</li><li>前端兜底：在路由层或动态导入处捕获加载失败，自动重试一次（换 cache-busting 参数），仍失败则提示&quot;版本已更新，请刷新页面&quot;并调用 <code>location.reload()</code>；Vite 可监听 <code>vite:preloadError</code> 事件，webpack 可捕获 <code>chunk</code> 加载失败。</li><li>长期机制：CDN 保留多个版本目录、构建产物按 release 分目录归档、Service Worker 缓存要随版本更新（<code>skipWaiting</code> + <code>clients.claim</code>），并在监控里对 <code>chunk</code> 加载失败单独设告警——它是&quot;缓存/发布流程坏了&quot;的第一信号。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么不能只靠刷新 CDN 解决？答：用户本地和中间节点的缓存不可控；正确做法是改动文件名，而不是指望所有缓存被刷掉。</li><li>陷阱：把 HTML 也设成长缓存，结果用户永远停在旧版本，是典型的版本不更新事故。</li><li>陷阱：<code>service worker</code> 缓存了旧 HTML 又没做版本更新，导致强制刷新都无效，排查时容易漏掉这一层。</li></ul><h3 id="q22-白屏怎么检测-有哪些方案-各有什么取舍" tabindex="-1"><a class="header-anchor" href="#q22-白屏怎么检测-有哪些方案-各有什么取舍" aria-hidden="true">#</a> Q22 白屏怎么检测？有哪些方案，各有什么取舍？</h3><p><strong>考察点</strong>：考白屏检测的多种实现思路与误判控制，能否给出可落地的组合方案。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：白屏检测没有单一可靠指标，生产上通常组合&quot;关键节点探针 + 一段时间内 DOM 是否有变化 + 屏幕采样点命中判断&quot;，并要求上报时附带足够现场信息。</p></blockquote><ol><li>关键节点探针：约定根容器（如 <code>#app</code>），在 <code>load</code> 后延迟 2-3 秒检查它是否存在、<code>innerHTML</code> 长度是否为 0、宽高是否为 0；最便宜，但换框架或改根节点就失效。</li><li>关键接口/就绪标记：在首屏数据渲染完成后打一个全局标记（如 <code>window.__PAGE_READY__</code>），超时未打标即判定异常；最贴近业务真实可用状态，误判率最低。</li><li><code>MutationObserver</code>：监听根容器在观察窗口内的变更次数，一次都没有说明页面根本没渲染出内容；能区分&quot;渲染太慢&quot;和&quot;完全没渲染&quot;。</li><li>屏幕采样点：用 <code>document.elementsFromPoint(x, y)</code> 在屏幕上按九宫格或网格取十几个点，如果绝大多数点命中的都是根容器、<code>body</code> 或 <code>html</code>，判定为白屏；这是最能反映&quot;用户眼里真的是一片白&quot;的方案。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">isBlank</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> pts <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">[</span><span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">0.5</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">0.2</span><span class="token punctuation">,</span> <span class="token number">0.2</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">0.8</span><span class="token punctuation">,</span> <span class="token number">0.2</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">0.2</span><span class="token punctuation">,</span> <span class="token number">0.8</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">0.8</span><span class="token punctuation">,</span> <span class="token number">0.8</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">0.3</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">0.7</span><span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> w <span class="token operator">=</span> innerWidth<span class="token punctuation">,</span> h <span class="token operator">=</span> innerHeight<span class="token punctuation">;</span>
  <span class="token keyword">const</span> blank <span class="token operator">=</span> pts<span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">[</span>rx<span class="token punctuation">,</span> ry<span class="token punctuation">]</span></span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> el <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">elementsFromPoint</span><span class="token punctuation">(</span>w <span class="token operator">*</span> rx<span class="token punctuation">,</span> h <span class="token operator">*</span> ry<span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token operator">!</span>el <span class="token operator">||</span> <span class="token punctuation">[</span><span class="token string">&#39;HTML&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;BODY&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">includes</span><span class="token punctuation">(</span>el<span class="token punctuation">.</span>tagName<span class="token punctuation">)</span> <span class="token operator">||</span> el<span class="token punctuation">.</span>id <span class="token operator">===</span> <span class="token string">&#39;app&#39;</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> blank<span class="token punctuation">.</span>length <span class="token operator">/</span> pts<span class="token punctuation">.</span>length <span class="token operator">&gt;=</span> <span class="token number">0.9</span><span class="token punctuation">;</span> <span class="token comment">// 九成采样点都空</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="5"><li>截图/骨架对比：在小程序容器或客户端 WebView 里可以截图与上一版本基准图做像素差异，准确但成本高、需要端上配合；Web 端一般不做实时截图。</li><li>误判与上报：加载中的骨架屏、全屏弹窗、深色主题都会干扰判断，所以要在&quot;页面进入 hidden 或超时后&quot;再判定，并且上报时带上 DOM 快照、资源失败列表、最近错误与接口状态——只报一句&quot;白屏&quot;等于没有信息量。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么不能只看 <code>#app.innerHTML === &#39;&#39;</code>？答：接口挂掉时框架可能渲染了一个空的容器或错误占位，<code>innerHTML</code> 不为空但用户看到的仍是白屏，所以要叠加屏幕采样。</li><li>陷阱：在 <code>load</code> 事件里立刻判断，慢网用户的正常首屏会被误报成白屏，必须给足等待时间并区分首屏与二次进入。</li><li>陷阱：白屏上报不带当时的资源与接口状态，定位时还得再复现一次，浪费最宝贵的止血时间。</li></ul><h3 id="q23-埋点-sdk-的设计要点有哪些-怎么保证埋点数据质量" tabindex="-1"><a class="header-anchor" href="#q23-埋点-sdk-的设计要点有哪些-怎么保证埋点数据质量" aria-hidden="true">#</a> Q23 埋点 SDK 的设计要点有哪些？怎么保证埋点数据质量？</h3><p><strong>考察点</strong>：深挖题。考 SDK 的架构取舍（体积、性能、可靠性、可维护性）与数据治理，不是只写一个 <code>track()</code> 函数。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：埋点 SDK 的设计围绕四条线展开——统一事件模型、队列与可靠投递、对业务性能影响最小、数据质量可校验；任何一条缺失，数据迟早不可信。</p></blockquote><ol><li>事件模型：统一为&quot;事件名 + 公共属性 + 自定义属性 + 上下文&quot;，公共属性包含 <code>appId</code>、<code>userId</code>/<code>deviceId</code>、<code>sessionId</code>、页面、<code>release</code>、渠道、时间戳；事件名用常量枚举集中管理，禁止散落字符串。</li><li>投递可靠性：内存队列 + 批量上报 + 失败本地缓存补发；每条事件生成唯一 <code>eventId</code> 用于服务端幂等去重；时间戳以服务端接收时间为准，客户端时间仅作参考。</li><li>性能与体积：SDK 异步加载，首屏关键路径上只保留极少量逻辑（或先入队后加载真正 SDK 再补发）；上报用 <code>sendBeacon</code>，空闲时用 <code>requestIdleCallback</code> 处理序列化；gzip 后控制在十几 KB 量级。</li><li>可维护性：提供 <code>debug</code> 模式在控制台打印即将上报的事件，便于联调与验收；对外 API 保持稳定（<code>init</code>/<code>track</code>/<code>setUser</code>/<code>setSuperProperties</code>/<code>flush</code>/<code>disable</code>）。</li><li>数据质量校验：埋点要有规范文档与命名约定（如 <code>模块_动作</code>），并在 CI 或测试环境加校验脚本，缺埋点、参数类型错误直接失败；关键漏斗要有人工对账（前端事件数 vs 后端业务订单数）来发现漏报与重复。</li><li>治理与合规：埋点有生命周期，下线功能要同步下线埋点，否则表越来越脏；不采集输入内容与敏感信息，支持一键关闭采集以应对合规要求。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：怎么发现埋点漏报？答：两条对账思路——前端事件量与服务端业务量比对（差异超阈值告警），以及用同一事件的 <code>eventId</code> 查重；再加上预发环境的自动化校验。</li><li>追问：SDK 报错会不会影响业务？答：必须全程 <code>try/catch</code> 且永不抛出，SDK 内部的异常只能自己吞掉并打日志，绝不能阻断业务流程。</li><li>陷阱：把 <code>track()</code> 写成同步发请求，用户快速点击时产生大量请求，既拖慢页面也把上报接口打挂。</li></ul><h3 id="q24-线上非常卡、疑似内存泄漏-怎么定位" tabindex="-1"><a class="header-anchor" href="#q24-线上非常卡、疑似内存泄漏-怎么定位" aria-hidden="true">#</a> Q24 线上非常卡、疑似内存泄漏，怎么定位？</h3><p><strong>考察点</strong>：深挖题。要求给出可执行的动作序列与判断依据，而不是罗列名词。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：卡顿先看主线程有没有长任务、有没有频繁重渲染；内存泄漏先用性能监视器看内存曲线是否只涨不落，再用三次堆快照对比找出未释放对象。</p></blockquote><ol><li>第一步确认影响面：用长任务与 INP 的上报数据，定位是全局卡还是特定页面、特定机型、特定版本；这一步决定后面是&quot;改代码&quot;还是&quot;先回滚&quot;。</li><li>卡顿定位动作序列：打开 Performance 面板录一段（至少包含一次卡顿）→ 看 Main 轨道上的长任务 → 展开调用树找到耗时函数 → 判断属于哪一类：大列表渲染、单次超大计算、频繁重渲染（React/Vue 的响应式触发过密）、还是强制同步布局（读写 <code>offsetHeight</code> 交替导致的重排）。</li><li>常见修法：长列表用虚拟滚动或分页；大计算搬进 Web Worker；高频事件防抖节流；避免在循环里读写布局属性；React 用 <code>memo</code>/<code>useMemo</code> 收敛重渲染，Vue 控制响应式粒度和 <code>v-once</code>/<code>v-memo</code> 的使用。</li><li>内存泄漏判断：用 Performance Monitor 看 JS Heap 与 DOM Nodes 曲线，反复进出同一页面若干次，如果每次回来内存台阶都上升、GC 后不回落，就基本确认泄漏。</li><li>内存泄漏定位动作序列：进入页面 → 手动 GC → 拍第一个堆快照 → 反复进出页面 3-5 次 → 再 GC 拍第二个快照 → 用 Comparison 视图对比新增对象；重点看 Detached DOM tree、持续增长的数组/Map、以及通过闭包或全局缓存被引用的对象。</li><li>高频泄漏源清单：未清理的 <code>setInterval</code>/<code>setTimeout</code>、未解绑的全局事件监听与 <code>resize</code>/<code>scroll</code> 监听、未 <code>disconnect</code> 的 <code>IntersectionObserver</code>/<code>MutationObserver</code>、未退订的事件总线或 WebSocket、挂在 <code>window</code> 上的大对象缓存、以及定时器或请求回调里闭包持有的旧组件实例。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：单次快照能看出泄漏吗？答：不能，必须做&quot;多次操作 + GC + 快照对比&quot;的增量分析，单张快照只能看当前占用。</li><li>追问：为什么反复进出页面必须是多次？答：一次进入的占用可能被浏览器缓存复用，重复几次后仍单调上升才是泄漏特征。</li><li>陷阱：只凭&quot;用户说卡&quot;就改代码，没有先确认影响面与版本，改完也无法验证是否修好。</li></ul><h3 id="q25-灰度发布和-feature-flag-的价值是什么-代价是什么" tabindex="-1"><a class="header-anchor" href="#q25-灰度发布和-feature-flag-的价值是什么-代价是什么" aria-hidden="true">#</a> Q25 灰度发布和 Feature Flag 的价值是什么？代价是什么？</h3><p><strong>考察点</strong>：深挖题。考察的是变更风险控制思维，以及能否说出它的成本，避免把它讲成万能药。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：灰度发布把&quot;一次性全量变更&quot;变成&quot;小流量试探&quot;，把故障影响面从全量压到 1%-5%；Feature Flag 进一步把代码发布与功能上线解耦，让止血变成&quot;关开关&quot;而不是&quot;发版本&quot;。</p></blockquote><ol><li>灰度的维度：按用户 ID 哈希百分比、地域、渠道、设备类型、内部员工白名单，通常先内测用户再 1% → 10% → 50% → 100%，每一档观察错误率与核心指标再放量。</li><li>核心价值：故障只影响小流量；能拿到新旧版本的真实数据对比（性能、转化），而不是只靠预发环境猜。</li><li>Feature Flag 的价值：代码已经发布但功能未开启，出问题秒级关停，不需要重新构建与发布；配合开关可以实现新老逻辑并行、AB 实验和&quot;随时回退&quot;。</li><li>关键前提：开关必须能动态下发 + 本地缓存兜底（下发失败时用缓存值，避免全量用户都拿不到配置）；开关的默认值要选&quot;安全侧&quot;。</li><li>代价一：分支逻辑变多，代码可读性下降，需要维护开关清单与清理计划，否则会积累成&quot;flag 债务&quot;，几年后没人敢删。</li><li>代价二：多版本共存会带来兼容问题（旧页面引用新接口、新老数据结构不一致），灰度期间的接口必须前后兼容，不能只靠前端开关；灰度也会让监控分析变复杂，必须按版本维度看数据。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：开关配置服务挂了怎么办？答：必须本地缓存 + 默认关闭（安全侧）兜底，并且开关只用于&quot;关掉新功能&quot;，不能把核心链路可用性押在开关服务上。</li><li>陷阱：把灰度当成&quot;不用测试&quot;的免死金牌，灰度只是缩小影响面，回归测试仍然必须做。</li><li>陷阱：忘记清理过期开关，导致分支爆炸，后续改动越来越不敢动——这是灰度最常见的长期成本。</li></ul><h3 id="q26-线上不能连调试器-有哪些调试手段" tabindex="-1"><a class="header-anchor" href="#q26-线上不能连调试器-有哪些调试手段" aria-hidden="true">#</a> Q26 线上不能连调试器，有哪些调试手段？</h3><p><strong>考察点</strong>：深挖题。考对真实线上调试渠道的掌握程度，包括安全边界的把握。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：线上调试靠&quot;可开关的日志面板 + 代抓包 + URL 调试参数 + 录制回放 + 远程调试&quot;五件套，共同原则是只对授权用户开放、不暴露敏感信息。</p></blockquote><ol><li>远程日志开关：URL 参数（如 <code>?debug=1</code>）或后端配置下发的开关控制日志等级，日志既打印到面板也上报；问题排查完必须能远程关闭，避免长期开启。</li><li>移动端面板：vConsole/eruda 提供 Network、Storage、Console、Elements 视图，是端内最快的手段；配合&quot;一键复制日志/导出截图&quot;给客服或研发。</li><li>代理抓包：Charles、Fiddler、mitmproxy 配置中间人证书，可以看到完整请求响应；手机端要装证书并信任，HTTPS 抓包要注意证书固定（SSL Pinning）的 App 抓不到。改包 mock 响应还能验证&quot;是不是接口数据问题&quot;。</li><li>URL 调试参数：除了 <code>debug</code>，常用 <code>mock=1</code> 走本地假数据、<code>sw=off</code> 关闭 Service Worker、<code>nocache=1</code> 强制拉新资源；这些参数要在代码里集中管理，并限制只对白名单/内网生效。</li><li>录制回放：Sentry Replay 或 rrweb 录制 DOM 变化与操作序列，可以像看视频一样重放用户操作，是复现&quot;偶现问题&quot;最有效的手段，前提是做好输入脱敏与合规告知。</li><li>远程调试：Android 用 <code>chrome://inspect</code> 连真机，iOS 用 Safari 的开发菜单；无法连线时用&quot;用户反馈附带日志与截图&quot;兜底，同时带上 <code>traceId</code> 到服务端日志里查完整链路。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>?debug=1</code> 会不会有安全风险？答：会。必须限制为白名单用户或内网，调试面板里的接口参数、存储内容、接口地址都属于敏感信息。</li><li>陷阱：用线上真实数据直接改包 mock，忽略后端可能因此产生的脏数据，mock 只应用于确认问题边界。</li><li>陷阱：忘记关调试开关，日志量和上报量暴增，成本与性能双双受损。</li></ul><h3 id="q27-告警应该怎么设计-为什么告警多了反而没人管" tabindex="-1"><a class="header-anchor" href="#q27-告警应该怎么设计-为什么告警多了反而没人管" aria-hidden="true">#</a> Q27 告警应该怎么设计？为什么告警多了反而没人管？</h3><p><strong>考察点</strong>：深挖题。考告警分级、抑制收敛与响应机制，核心是&quot;告警要被信任&quot;，答出告警疲劳的成因才算深入。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：告警设计的目标是&quot;该响的必响、不该响的不响&quot;，靠分级定响应时效、靠抑制与收敛防风暴、靠定期治理保持信噪比。</p></blockquote><ol><li>分级：P0 全站不可用（白屏率飙升、核心接口全挂）电话 + 群 @全员；P1 核心链路受损（下单失败率超阈值）立即通知值班；P2 局部功能异常当日处理；P3 体验指标劣化进日报。级别直接绑定响应时效与升级路径。</li><li>阈值设计：用&quot;错误率 + 持续时间 + 影响用户数&quot;三个条件组合，例如核心接口 5 分钟内失败率 &gt; 1% 且影响用户 &gt; 100 才触发，避免瞬时抖动误报；基线取自历史分位数而不是拍脑袋。</li><li>抑制（Suppression）：同一指纹在窗口期内只告警一次，静默期内只累计不重复通知；维护发布期静默名单（发布后 10 分钟内的已知错误不告警），但要标注&quot;静默不等于不记录&quot;。</li><li>收敛（Aggregation）：按根因聚合而不是按条数告警，一次事件只发一条；错误风暴时自动降级为&quot;汇总告警 + 看板链接&quot;，避免群里几百条消息把真正的问题淹没。</li><li>值班与响应：明确值班人与备份人、响应时效（如 P0 5 分钟响应、15 分钟止血）、超时自动升级到主管；告警必须可认领、可标记&quot;处理中/已恢复&quot;，形成闭环。</li><li>告警治理：定期复盘告警准确率与无效告警占比，删除长期无人处理的告警项，补充缺失的监控项；告警数量不是越多越好，能被人信任的少量告警才有效。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么告警多了等于没有告警？答：人会对持续噪声脱敏，最终所有告警都被忽略；一条真实 P0 混在几百条噪声里，响应时间会显著变长。</li><li>陷阱：只按&quot;单条错误出现&quot;就告警，没有窗口期与影响面条件，一有抖动就响，这就是告警疲劳的根源。</li><li>陷阱：告警只发到一个没人看的邮件列表，缺少值班与升级机制，等同于没告警。</li></ul><h3 id="q28-怎么做复盘和预防-让同类事故不再发生" tabindex="-1"><a class="header-anchor" href="#q28-怎么做复盘和预防-让同类事故不再发生" aria-hidden="true">#</a> Q28 怎么做复盘和预防，让同类事故不再发生？</h3><p><strong>考察点</strong>：深挖题。考工程闭环能力：从&quot;修好这一个 bug&quot;升级到&quot;让这一类 bug 进不来&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：复盘要产出可验证的改进项，预防要把卡口前移——监控前置、E2E 覆盖核心链路、预发与线上同构、发布可回滚可灰度。</p></blockquote><ol><li>复盘文档四要素：时间线（首次发生、发现、止血、恢复）、影响面（用户数、订单/金额、时长）、根因（连续追问&quot;为什么&quot;直到流程或设计层面）、改进项（每条必须有责任人和截止时间，且可验证）。</li><li>复盘必须回答的一个问题：这次为什么没有被监控提前发现？答案通常指向&quot;缺埋点/缺白屏检测/告警阈值太松&quot;，这些比 bug 本身更值得修。</li><li>监控前置：新功能上线时同步上线错误监控、关键埋点与告警，把监控纳入开发完成定义（DoD），而不是等出事后补。</li><li>E2E 兜底：用 Playwright/Cypress 覆盖登录、下单、支付这类核心链路，在预发与发布后各跑一次冒烟，把&quot;用户能走通主流程&quot;变成自动化断言。</li><li>预发与线上同构：预发必须包含 CDN、网关、真实构建产物与缓存策略，否则&quot;预发好的、线上一发布就白屏&quot;会反复出现；差异越大，预发越没有价值。</li><li>发布卡口：CI 强制类型检查与构建检查、灰度分批放量、一键回滚预案、发布窗口避开业务高峰、发布后 10 分钟内专人盯监控看板；变更与错误曲线的关联分析要成为固定动作。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：复盘会不会变成追责会？答：定位到人的复盘会让人隐瞒信息，正确做法是对事不对人，关注流程与系统缺陷，才能拿到真实时间线。</li><li>陷阱：改进项写成&quot;加强测试意识&quot;&quot;提高代码质量&quot;这种无法验证的口号，等于没有改进。</li><li>陷阱：只修 bug 不做卡口，同类问题会在下一次发布时以另一种形式复发，这是最典型的&quot;假闭环&quot;。</li></ul><h2 id="本章小结" tabindex="-1"><a class="header-anchor" href="#本章小结" aria-hidden="true">#</a> 本章小结</h2><ul><li>监控三块各有分工：错误监控回答&quot;哪里坏了&quot;，性能监控回答&quot;哪里慢了&quot;，行为埋点回答&quot;用户做了什么&quot;，三者必须共用 userId、sessionId、release 才能拼出时间线。</li><li><code>window.onerror</code> 只抓 JS 运行时错误且只能挂一个；资源加载失败必须在 <code>window</code> 上以捕获阶段监听 <code>error</code>，并用 <code>instanceof ErrorEvent</code> 区分两类事件。</li><li>Promise 拒绝要用 <code>unhandledrejection</code> 兜住，且 <code>reason</code> 可能不是 Error；框架层错误靠 Vue 的 <code>app.config.errorHandler</code> 与 React 错误边界的 <code>componentDidCatch</code> 收口，但它们都抓不到事件回调与异步错误。</li><li>跨域脚本报错被抹成 <code>Script error.</code>，解决方案是 <code>&lt;script crossorigin=&quot;anonymous&quot;&gt;</code> 与 CDN 的 <code>Access-Control-Allow-Origin</code> 同时具备，缺一不可。</li><li>上报设计记住四件事：错误全量、性能与埋点采样、指纹去重聚合、队列限流加批量；页面卸载时的数据用 <code>sendBeacon</code> 在 <code>visibilitychange</code> 转 hidden 时发。</li><li>生产环境用 <code>hidden-source-map</code> 生成 map 并私有上传，按 release 归档，用 <code>originalPositionFor</code> 按行列还原，版本对不上是还原失败的头号原因。</li><li>排查线上问题永远是&quot;先止血（回滚/降级/开关）→ 再定位 → 再修复 → 复盘&quot;，恢复服务优先于查清根因。</li><li>白屏检测没有单一指标，生产上用关键节点探针 + 就绪标记 + <code>MutationObserver</code> + <code>elementsFromPoint</code> 屏幕采样组合判断，并在上报时附带 DOM 快照、资源失败与最近错误。</li></ul>`,209);function p(l,i){return s(),a("div",null,[c,o(" COUNT: 28 ")])}const u=n(t,[["render",p],["__file","20-monitoring-debugging.html.vue"]]);export{u as default};
